<?php require __DIR__.'/layout/header.php'; ?><h2>Shopping Cart</h2><?php foreach($items as $item): ?><div class="cart-item"><b><?=e($item['name'])?></b> — <?=e($item['price'])?> × <?=$item['quantity']?> = <?=e($item['subtotal'])?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$item['id']?>"><input type="number" min="1" max="99" name="quantity" value="<?=$item['quantity']?>"><button name="action" value="update">Update</button><button name="action" value="remove">Remove</button></form></div><?php endforeach; ?><h3>Total: <?=e($total)?></h3><?php if($items): ?><form method="post" action="index.php?route=checkout"><?=csrf_field()?><button>Checkout</button></form><?php else: ?><p>Your cart is empty.</p><?php endif; ?><?php require __DIR__.'/layout/footer.php'; ?>
